import os
import re
import hashlib
import hmac
from flask import Flask, request, jsonify
from jinja2.sandbox import SandboxedEnvironment
from jinja2 import BaseLoader
from markupsafe import Markup

app = Flask(__name__)
app.secret_key = os.urandom(32)

# Custom filters for the notification system
def highlight_filter(value, pattern):
    """Highlight matching patterns in text with HTML markup."""
    if not pattern or not value:
        return value
    # Use the pattern to create highlighted version
    try:
        highlighted = re.sub(
            f'({re.escape(pattern)})',
            r'<mark>\1</mark>',
            str(value)
        )
        return Markup(highlighted)
    except Exception:
        return value

def dynamic_format_filter(value, spec):
    """Apply dynamic formatting specification to a value.
    Supports: upper, lower, title, truncate:N, default:val"""
    if not spec:
        return value
    parts = spec.split(':')
    cmd = parts[0].lower()
    if cmd == 'upper':
        return str(value).upper()
    elif cmd == 'lower':
        return str(value).lower()
    elif cmd == 'title':
        return str(value).title()
    elif cmd == 'truncate' and len(parts) > 1:
        try:
            n = int(parts[1])
            return str(value)[:n] + '...' if len(str(value)) > n else str(value)
        except ValueError:
            return value
    elif cmd == 'default' and len(parts) > 1:
        return value if value else parts[1]
    return value

class TemplateEngine:
    """Secure template engine with sandboxed environment."""

    def __init__(self):
        self._env = SandboxedEnvironment(
            loader=BaseLoader(),
            autoescape=False
        )
        self._env.filters['highlight'] = highlight_filter
        self._env.filters['dynformat'] = dynamic_format_filter
        self._templates = {}
        self._compiled_cache = {}
        self._register_defaults()

    def _register_defaults(self):
        self._templates['welcome'] = 'Hello {{ username }}! Welcome to {{ service_name }}.'
        self._templates['alert'] = 'ALERT for {{ username }}: {{ message }}'
        self._templates['digest'] = 'Daily digest for {{ username }}:\n{% for item in items %}  - {{ item }}\n{% endfor %}'
        self._templates['custom_greeting'] = 'Hi {{ username | dynformat(format_spec) }}! {{ message }}'

    def render(self, template_name, context):
        """Render a registered template with the given context."""
        if template_name not in self._templates:
            return None

        cache_key = template_name
        if cache_key not in self._compiled_cache:
            self._compiled_cache[cache_key] = self._env.from_string(
                self._templates[template_name]
            )

        return self._compiled_cache[cache_key].render(**context)

    def render_composite(self, template_name, context, wrapper=None):
        """Render a template with optional wrapper formatting.

        The wrapper allows post-processing the rendered output with
        additional context substitution for layout purposes.
        """
        base_output = self.render(template_name, context)
        if base_output is None:
            return None

        if wrapper:
            # Apply wrapper template for layout formatting
            # wrapper is expected to be a registered template name
            # but we support inline layout strings for flexibility
            layout_context = {**context, 'content': base_output}
            layout_tpl = self._env.from_string(wrapper)
            return layout_tpl.render(**layout_context)

        return base_output

    def register(self, name, template_str, admin_key):
        """Register a new template (admin only)."""
        expected = hmac.new(app.secret_key, b'admin-register', hashlib.sha256).hexdigest()
        if not hmac.compare_digest(admin_key, expected):
            return False
        self._templates[name] = template_str
        if name in self._compiled_cache:
            del self._compiled_cache[name]
        return True

engine = TemplateEngine()

@app.route('/api/notifications/render', methods=['POST'])
def render_notification():
    """Render a notification using a registered template."""
    data = request.get_json()
    if not data or 'template' not in data:
        return jsonify({'error': 'Missing template name'}), 400

    template_name = data['template']
    context = data.get('context', {})
    wrapper = data.get('wrapper', None)

    # Validate template name exists
    if template_name not in engine._templates:
        return jsonify({'error': f'Unknown template: {template_name}'}), 404

    # Sanitize context - only allow string/list/int values
    safe_context = {}
    for k, v in context.items():
        if isinstance(v, (str, int, float, bool)):
            safe_context[k] = v
        elif isinstance(v, list) and all(isinstance(i, (str, int, float)) for i in v):
            safe_context[k] = v

    try:
        result = engine.render_composite(template_name, safe_context, wrapper=wrapper)
        if result is None:
            return jsonify({'error': 'Render failed'}), 500
        return jsonify({'rendered': result, 'template': template_name})
    except Exception as e:
        return jsonify({'error': 'Template rendering error'}), 500

@app.route('/api/notifications/templates', methods=['GET'])
def list_templates():
    """List available template names."""
    return jsonify({'templates': list(engine._templates.keys())})

@app.route('/api/notifications/preview', methods=['POST'])
def preview_template():
    """Preview a template with sample data."""
    data = request.get_json()
    if not data or 'template' not in data:
        return jsonify({'error': 'Missing template name'}), 400

    template_name = data['template']
    sample_context = {
        'username': 'TestUser',
        'message': 'This is a preview',
        'service_name': 'NotifyService',
        'items': ['Item 1', 'Item 2', 'Item 3'],
        'format_spec': 'title'
    }

    try:
        result = engine.render(template_name, sample_context)
        if result is None:
            return jsonify({'error': 'Template not found'}), 404
        return jsonify({'preview': result})
    except Exception as e:
        return jsonify({'error': 'Preview failed'}), 500

if __name__ == '__main__':
    app.run(debug=False, host='127.0.0.1', port=5000)
